package com.personal.meditation;
import static org.junit.Assert.*;import android.content.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class)@Config(sdk=28)public class SettingsTest{
 private Settings settings;private Context context;@Before public void reset(){context=RuntimeEnvironment.getApplication();context.getSharedPreferences("meditation_settings",0).edit().clear().commit();settings=new Settings(context);}
 @Test public void defaultsAreSimpleAndSeparate(){JSONObject s=settings.get();assertEquals(10,s.optInt("minutes"));assertEquals("soft_bell",s.optString("bell"));assertTrue(s.optJSONObject("vibrations").optJSONObject("quarter").optBoolean("enabled"));assertFalse(s.optJSONObject("vibrations").optJSONObject("start").optBoolean("enabled"));assertEquals(900,s.optJSONObject("vibrations").optJSONObject("end").optInt("ms"));assertFalse(context.getSharedPreferences("route_manager",0).contains("minutes"));}
 @Test public void customSoundsAndCueLengthsPersist()throws Exception{assertTrue(settings.custom("quarter","content://test/audio","My bell.wav"));JSONObject s=settings.get();s.put("minutes",7).put("bell","warm_bowl");s.getJSONObject("vibrations").getJSONObject("quarter").put("ms",350).put("enabled",false);assertTrue(settings.save(s.toString()));JSONObject saved=new Settings(context).get();assertEquals(7,saved.getInt("minutes"));assertEquals("warm_bowl",saved.getString("bell"));assertEquals("custom",saved.getString("quarter"));assertEquals(350,saved.getJSONObject("vibrations").getJSONObject("quarter").getInt("ms"));assertFalse(saved.getJSONObject("vibrations").getJSONObject("quarter").getBoolean("enabled"));}
 @Test public void invalidSettingsCannotPartiallyReplaceSavedChoices()throws Exception{String original=settings.get().toString();for(int duration:new int[]{0,241}){JSONObject s=settings.get().put("minutes",duration);assertFalse(settings.save(s.toString()));assertEquals(original,settings.get().toString());}JSONObject s=settings.get().put("minutes",20);s.getJSONObject("vibrations").getJSONObject("prepLong").put("ms",2000);assertFalse(settings.save(s.toString()));assertEquals(original,settings.get().toString());assertFalse(settings.save(settings.get().put("quarter","custom").toString()));assertEquals(original,settings.get().toString());}
 @Test public void newGongAndOldSoundIdentifiersBothRemainValid()throws Exception{JSONObject data=settings.get().put("bell","temple_gong").put("quarter","warm_bowl");assertTrue(settings.save(data.toString()));assertEquals("temple_gong",new Settings(context).get().getString("bell"));assertEquals("warm_bowl",new Settings(context).get().getString("quarter"));}
}
